#: Les grands modèles connus le jour où la règle a été posée. Recopiés ici plutôt
#: que lus sur le modèle : une migration est une photographie, et elle doit
#: continuer à semer exactement ceux-là le jour où la liste aura changé en base.
GRANDS_AU_DEPART = ["MODELE L", "MODELE XL", "QUATTRO", "COLLAB",
                    "XL (2modules)", "XL (3modules)"]


def basculer(apps, schema_editor):
    """Trois places deviennent deux, et les grands modèles sont semés.

    Trois choses, dans cet ordre :

    1. Les emplacements réglés sur « gmd » passent à « gd ». Le code du mode
       change, pas la travée : c'est la même étagère, avec une place de moins.

    2. Les occupations en place « Milieu » sont DÉTACHÉES — la cabine redevient
       « non rangée » et ressort dans la liste à ranger. Elles ne pouvaient pas
       rester : « M » n'est plus une place, et l'écran d'occupation aurait affiché
       une travée dont une cabine est nulle part. Les déplacer d'office vers
       Gauche ou Droite était l'autre option ; elle écrit une position que
       personne n'a vérifiée devant le rack, et une position fausse est pire
       qu'une position absente. Le journal garde le rangement d'origine.

    3. Les six grands modèles sont créés, ni plus ni moins. Un modèle déjà réglé
       n'est pas retouché : si quelqu'un a dit « QUATTRO est normale », la
       migration ne le contredit pas.
    """
    Emplacement = apps.get_model("wms", "Emplacement")
    Occupation = apps.get_model("wms", "Occupation")
    ModeleCabine = apps.get_model("wms", "ModeleCabine")

    Emplacement.objects.filter(mode_places="gmd").update(mode_places="gd")
    Occupation.objects.filter(place="M").update(emplacement=None, place="")

    for nom in GRANDS_AU_DEPART:
        cle = " ".join(nom.split()).upper()
        if not ModeleCabine.objects.filter(cle=cle).exists():
            ModeleCabine.objects.create(nom=nom, cle=cle, grand=True)


def rebasculer(apps, schema_editor):
    """Retour en arrière : le mode reprend son ancien code.

    Les occupations détachées ne se rattachent pas — on ne sait plus où elles
    étaient, et le journal est le seul à le savoir. Les modèles semés restent :
    ils ne gênent rien, et les supprimer effacerait un réglage fait à la main.
    """
    Emplacement = apps.get_model("wms", "Emplacement")
    Emplacement.objects.filter(mode_places="gd").update(mode_places="gmd")


